import{K as l,a as r,c as i,b as t,k as s,q as c,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Excel 实战：建立可刷新、可核对的月报","description":"用八条订单串联数据录入、规则检查、SUMIFS、Power Query、透视表和图表，制作 2026 年 10 月月报并用独立结果交叉核对。","frontmatter":{"title":"Excel 实战：建立可刷新、可核对的月报","description":"用八条订单串联数据录入、规则检查、SUMIFS、Power Query、透视表和图表，制作 2026 年 10 月月报并用独立结果交叉核对。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"实践案例","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Excel 表格与数据分析","summary":"用八条订单串联数据录入、规则检查、SUMIFS、Power Query、透视表和图表，制作 2026 年 10 月月报并用独立结果交叉核对。","status":"active","related":[{"title":"Access 查询、窗体、报表与维护","link":"/tools/office/access/forms","kind":"使用指南","scope":"general","audience":"general"},{"title":"Access 入门、表设计与数据关系","link":"/tools/office/access/data","kind":"使用指南","scope":"general","audience":"general"},{"title":"Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH","link":"/tools/office/excel/lookup","kind":"使用指南","scope":"general","audience":"general"},{"title":"Excel 打印、导出与工作簿交付","link":"/tools/office/excel/printing","kind":"使用指南","scope":"general","audience":"general"},{"title":"Excel 公式、相对引用与绝对引用","link":"/tools/office/excel/formulas","kind":"使用指南","scope":"general","audience":"general"}],"prev":{"text":"Excel 打印、导出与工作簿交付","link":"/tools/office/excel/printing"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Excel 打印、导出与工作簿交付","link":"/tools/office/excel/printing"},"next":false},"headers":[],"relativePath":"tools/office/excel/project.md","filePath":"tools/office/excel/project.md"}'),d={name:"tools/office/excel/project.md"},f=Object.assign(d,{setup(h){const a={path:"/tools/office/excel/project",app:"Excel",title:"完整跑通一次月报变更与交付",steps:[{tab:"公式",command:"SUMIFS",setting:"月份：2026-10；状态：已完成；金额：3160",anchor:"walkthrough-1"},{tab:"数据",command:"全部刷新",setting:"等待查询完成；再刷新透视表",anchor:"walkthrough-2"},{tab:"文件",command:"导出",setting:"恢复基准数据；交付金额：3160",anchor:"walkthrough-3"}]};return(p,e)=>{const o=l("OfficeGuide");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"excel-实战-建立可刷新、可核对的月报",tabindex:"-1"},[s("Excel 实战：建立可刷新、可核对的月报 "),t("a",{class:"header-anchor",href:"#excel-实战-建立可刷新、可核对的月报","aria-label":'Permalink to "Excel 实战：建立可刷新、可核对的月报"'},"​")],-1)),e[1]||(e[1]=t("p",null,"本篇交付“2026 年 10 月已完成订单月报”。成功标准是读者能看懂数据口径，你能追溯明细，追加数据后能刷新，并能用两种方式核对结果。",-1)),c(o,{guide:a}),e[2]||(e[2]=n(`<h2 id="scope" tabindex="-1">明确口径与结构 <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;明确口径与结构 {#scope}&quot;">​</a></h2><p>使用<a href="/tools/office/excel/start#data">八条订单</a>。统计范围是日期大于等于 2026-10-01、早于 2026-11-01，且状态为已完成。金额按数量乘单价计算，本练习不含折扣、退款和税费。真实报表如有这些规则，应先明确再修改计算。</p><p>工作簿安排为：<code>订单</code> 保存明细和检查列，<code>产品</code> 保存匹配字典，<code>参数</code> 保存统计月，<code>汇总</code> 放指标与图表，<code>部门透视</code> 用于核对。原始导出文件放在独立目录，避免只剩经过修改的工作簿。</p><h2 id="formulas" tabindex="-1">建立检查和指标 <a class="header-anchor" href="#formulas" aria-label="Permalink to &quot;建立检查和指标 {#formulas}&quot;">​</a></h2><p>先确认订单号唯一、日期为数值、数量和单价为有效数字、状态属于字典。原始八行金额总计必须为 5120。检查错误未解决前，不先制作漂亮图表。</p><p>在 <code>参数!B2</code> 输入真实日期 2026-10-01，在 B3 输入 <code>=EDATE(B2,1)</code>。汇总公式：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=SUMIFS(Sales[金额],Sales[状态],&quot;已完成&quot;,Sales[日期],&quot;&gt;=&quot;&amp;参数!$B$2,Sales[日期],&quot;&lt;&quot;&amp;参数!$B$3)</span></span>
<span class="line"><span>=COUNTIFS(Sales[状态],&quot;已完成&quot;,Sales[日期],&quot;&gt;=&quot;&amp;参数!$B$2,Sales[日期],&quot;&lt;&quot;&amp;参数!$B$3)</span></span></code></pre></div><p>金额应为 <strong>3160</strong>，订单数为 <strong>5</strong>。若一张真实订单有多条明细，第二式统计的是明细行数，不再是唯一订单数；应按真实数据粒度改用去重计数等方法。</p><h2 id="reconcile" tabindex="-1">用透视表独立核对 <a class="header-anchor" href="#reconcile" aria-label="Permalink to &quot;用透视表独立核对 {#reconcile}&quot;">​</a></h2><p>建立部门透视表，值为金额求和，状态筛选已完成，日期筛选 10 月。预期结果如下：</p><table tabindex="0"><thead><tr><th>范围</th><th style="text-align:right;">行数</th><th style="text-align:right;">金额</th></tr></thead><tbody><tr><td>全部原始订单</td><td style="text-align:right;">8</td><td style="text-align:right;">5120</td></tr><tr><td>全部已完成订单</td><td style="text-align:right;">6</td><td style="text-align:right;">4060</td></tr><tr><td>10 月已完成订单</td><td style="text-align:right;">5</td><td style="text-align:right;">3160</td></tr><tr><td>10 月运营已完成</td><td style="text-align:right;">3</td><td style="text-align:right;">2440</td></tr><tr><td>10 月技术已完成</td><td style="text-align:right;">2</td><td style="text-align:right;">720</td></tr></tbody></table><p>财务没有符合口径的已完成记录。报表若必须展示所有部门，需要从完整部门列表出发显示零；透视结果没有财务行不一定表示源数据中没有财务部门。</p><p>公式和透视结果不一致时，按数据源范围、刷新状态、日期类型、筛选状态、汇总方式和重复记录的顺序排查。不要调整公式中的数字硬凑到想要的结果。</p><h2 id="refresh" tabindex="-1">加入查询与图表 <a class="header-anchor" href="#refresh" aria-label="Permalink to &quot;加入查询与图表 {#refresh}&quot;">​</a></h2><p>来源每月需要重复清洗时，按<a href="/tools/office/excel/power-query">Power Query 教程</a>保存步骤，保留错误记录检查。查询结果可以作为透视源；若一部分公式读原始表、另一部分图表读清洗结果，须明确两者是否采用相同口径，避免双份数据各自更新。</p><p>汇总页展示统计月份、完成金额、完成订单数、部门金额柱形图和说明。题目写“2026 年 10 月已完成订单金额”，不要写成无范围的“收入”。记录刷新时间和数据截止时间，两者不是同一个概念。</p><h2 id="practice" tabindex="-1">变更测试与交付 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;变更测试与交付 {#practice}&quot;">​</a></h2><p>先在副本把 O004 数量从 5 改成 6，金额应从 400 变成 480，月报应从 3160 增加到 3240。然后把 O003 状态改为已完成，再增加 900，变为 4140。最后把参数改为 11 月，原始数据范围内应只有 O008，金额为 900。</p><p>逐项恢复测试修改，确认 10 月结果回到 3160。保存可编辑文件，按<a href="/tools/office/excel/printing">打印教程</a>导出 PDF，交付说明写明数据范围、计算规则、刷新步骤和异常处理方法。这里列的是练习预期，不代表已在你的实际 Office 环境执行过。</p><h2 id="walkthrough" tabindex="-1">图示跟做：完整跑通一次月报变更与交付 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：完整跑通一次月报变更与交付 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：把口径和源表分开管理 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：把口径和源表分开管理 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：公式 → SUMIFS。</strong></p><p>建立原始明细、参数、汇总、检查四类工作表，明确本月起止日期和完成状态。使用本专题 Sales 表，分别检查订单数八条、全部金额 5120、已完成金额 4060、十月已完成金额 3160。先解决核对差异，再进入展示图表。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：用变更测试暴露断开的环节 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：用变更测试暴露断开的环节 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：数据 → 全部刷新。</strong></p><p>在副本把 O004 数量改为 6，确认源金额先变为 480，刷新查询，再刷新依赖查询的透视表；十月金额应为 3240。再把 O003 状态从待处理改为已完成，结果应为 4140。观察公式、透视表与图表是否都到达同一版本。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：恢复基准并输出可复查版本 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：恢复基准并输出可复查版本 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：文件 → 导出。</strong></p><p>恢复 O004 数量 5、O003 待处理，重新完成全部刷新和核对，回到 3160。记录数据截止时间、源文件、筛选口径和刷新顺序，再导出阅读版。需要他人继续更新时一并提供可编辑工作簿及数据源访问说明，不能只给一张图。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>查询还在后台运行时就导出，会得到新旧数据混合的材料。验收记录应写实际行数、总额和刷新完成状态，不能只写“已刷新”。</p>`,32))])}}});export{g as __pageData,f as default};
